"use client";

import { useQuery } from "convex/react";
import { api } from "@convex/api";

export default function TasksPage() {
  const tasks = useQuery(api.admin.listActiveTasks);

  return (
    <div>
      <h1 style={{ fontSize: 24, fontWeight: 700, marginBottom: 20 }}>Tasks</h1>
      <div className="card">
        <table>
          <thead>
            <tr>
              <th>Type</th>
              <th>Platform</th>
              <th>Target</th>
              <th>Points</th>
              <th>Verifier</th>
              <th>Expires</th>
            </tr>
          </thead>
          <tbody>
            {tasks?.map((t) => (
              <tr key={t._id}>
                <td>{t.type}</td>
                <td>{t.platform}</td>
                <td style={{ maxWidth: 200, overflow: "hidden", textOverflow: "ellipsis" }}>{t.targetUrl || "—"}</td>
                <td>{t.points}</td>
                <td><span className="badge badge-gray">{t.verifier}</span></td>
                <td>{new Date(t.expiresAt).toLocaleDateString()}</td>
              </tr>
            ))}
            {(!tasks || tasks.length === 0) && (
              <tr><td colSpan={6} style={{ color: "#71717a", textAlign: "center", padding: 20 }}>No active tasks</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
